    for index, choices in enumerate(options):
        viable = [
            i
            for i in range(len(choices))
            if not _blocked_everywhere(options, index, i)
        ]
        if best is None or len(viable) < best[0]:
            blocked = _blockers(options, index)
            explanation = None
            if viable:
